In C, assignment operators are used to assign values to variables. The left operand is the variable and the right operand is the value being assigned. The value on the right must match the data type of the variable otherwise, the compiler will raise an error.
            C

    #include <stdio.h>
int main()
{

    // Assigning value 10 to a using "=" operator
    int a = 10;
    printf("%d", a);
    return 0;
}

Output10Explanation: In the above example, the assignment operator (=) is used to assign the value 10 to the variable a. The printf() function then prints the value of a, which is 10, to the console.Compound Assignment OperatorsC also provides compound assignment operators that combine an operation and assignment in a single step. They make the code shorter and more efficient.Here are the most commonly used compound assignment operators:1. Addition Assignment (+=)Adds the value of the right operand to the left operand and stores the result in the left operand.
            C

    #include <stdio.h>
int main()
{
    int a = 5;

    // Equivalent to a = a + 3
    a += 3;
    printf("%d", a);
    return 0;
}

Outputa = 82. Subtraction Assignment (-=)Subtracts the value of the right operand from the left operand and stores the result in the left operand.
            C

    #include <stdio.h>
int main()
{
    int a = 10, b = 5;

    // a = a - b
    a -= b;
    printf("%d", a);
    return 0;
}

Output53. Multiplication Assignment (*=)Multiplies the value of the right operand by the left operand and stores the result in the left operand.
            C

    #include <stdio.h>
int main()
{
    int a = 10, b = 5;

    // a = a * b
    a *= b;
    printf("%d", a);
    return 0;
}

Output504. Division Assignment (/=)Divides the left operand by the right operand and stores the result in the left operand.
            C

    #include <stdio.h>

int main()
{
    int a = 10, b = 5;

    // a = a / b
    a /= b;
    printf("%d", a);
    return 0;
}

Output25. Modulus Assignment (%=)Takes the modulus of the left operand by the right operand and stores the result in the left operand.
            C

    #include <stdio.h>

int main()
{
    int a = 10, b = 5;

    // a = a % b
    a %= b;
    printf("%d", a);
    return 0;
}

Output06. Bitwise AND Assignment (&=)Performs a bitwise AND operation and assigns the result.
            C

    #include <stdio.h>

int main()
{

    // 60 = 0011 1100 in binary
    int a = 60;

    // 13 = 0000 1101 in binary
    int b = 13;

    // Bitwise AND Assignment a = a & b -> 60 & 13 = 12 (0000 1100 in binary)
    a &= b;
    printf("%d", a);

    return 0;
}

Output127. Bitwise OR Assignment (|=)Performs a bitwise OR operation and assigns the result.
            C

    #include <stdio.h>

int main()
{

    // 60 = 0011 1100 in binary
    int a = 60;

    // 13 = 0000 1101 in binary
    int b = 13;

    // Bitwise OR Assignment a = a | b -> 60 | 13 = 61 (0011 1101 in binary)
    a |= b;
    printf("a |= b: %d\n", a);

    return 0;
}

Outputa |= b: 61
8. Bitwise XOR Assignment (^=)Performs a bitwise XOR operation and assigns the result.
            C

    #include <stdio.h>
int main()
{

    // 60 = 0011 1100 in binary
    int a = 60;

    // 13 = 0000 1101 in binary
    int b = 13;

    // a = a ^ b -> 60 ^ 13 = 49 (0011 0001 in binary)
    a ^= b;
    printf("%d", a);
    return 0;
}

9. Bitwise Left Shift Assignment (<<=)Shifts the bits of the left operand to the left by the number of positions specified by the right operand and assigns the result.
            C

    #include <stdio.h>

int main()
{

    // 60 = 0011 1100 in binary
    int a = 60;

    // 13 = 0000 1101 in binary
    int b = 13;

    // Bitwise Left Shift Assignment a = a << 2 -> 60 << 2 = 240 (1111 0000 in binary)
    a <<= 2;
    printf("%d", a);

    return 0;
}

Output24010. Bitwise Right Shift Assignment (>>=)Shifts the bits of the left operand to the right by the number of positions specified by the right operand and assigns the result.
            C

    #include <stdio.h>

int main()
{

    // 60 = 0011 1100 in binary
    int a = 60;

    // 13 = 0000 1101 in binary
    int b = 13;

    // Bitwise Right Shift Assignment a = a >> 2 -> 60 >> 2 = 15 (0000 1111 in binary)
    a >>= 2;
    printf("%d", a);
    return 0;
}

Output15
